window.ME_DATA = window.ME_DATA || {};
window.ME_DATA["y9-me"] = [
 {
  id:"l1", lesson:1, title:"Ethics in the Context of Communities", unit:"Unit 1: Ethics in Communities & Nations", art:"community",
  dna:"Think about the community you live in (your building, neighbourhood or area). Write down ONE thing people do that makes it a good place to live, and ONE thing that would make it worse if people stopped doing it.",
  dnaQs:["Name ONE thing people in your community do that makes it a good place to live.","Name ONE thing that would make your community worse if people stopped doing it.","What does this tell you about how individuals affect a community?"],
  dnaHint:"A good answer names specific actions, such as greeting neighbours, keeping shared spaces clean, driving safely or helping during Ramadan iftars, and explains that a community depends on the choices of the individuals in it.",
  intentions:["Understand what a community is and what makes community life ethical.","Explore the rights and responsibilities individuals have as members of a community.","Apply ethical ideas to judge how a community should respond to a real situation."],
  criteria:["I can explain what a community is and give examples of different communities.","I can describe the rights and responsibilities of community members.","I can apply ethical ideas to judge a community scenario."],
  concept:{key:"Communities", related:"Responsibility, Ethics", soi:"Communities thrive when their members act ethically and accept shared responsibilities.", context:"Identities and Relationships — exploring how individuals belong to and shape the communities around them.", uae:"The UAE's 'Year of Community' (2025) and Emirati traditions of neighbourliness (al-jar) and volunteering; links to Individuals & Societies."},
  words:[["Community","A group of people who share a place, interests, values or identity."],["Ethics","Principles that guide people in deciding what is right and wrong."],["Common good","What benefits all or most members of a community, not just a few."],["Rights","Things every person is entitled to, such as safety and fair treatment."],["Civic responsibility","The duties a person has as a member of a community, such as obeying laws and helping others."],["Volunteering","Freely giving time or effort to help others without being paid."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE real community initiative in the UAE (e.g. a beach or desert clean-up, a Ramadan iftar distribution, a community fridge, a volunteering platform).","Research it using at least two reliable sources.","Record: what the initiative does, who it helps, and which community responsibility it reflects.","Note one way students your age could take part."], prompts:["The initiative I chose and my two sources","What it does and who it helps","The community responsibility it reflects","One way students my age could take part"], success:"Good examples include community clean-up campaigns, Ramadan iftar tents and meal distributions, community fridges, and national volunteering platforms. Strong answers link the initiative to a clear ethical idea (e.g. the common good, caring for neighbours, protecting shared spaces) rather than only describing it. For the top band, use two credible sources and suggest a realistic, age-appropriate way to get involved."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"In a residential community, the shared park has become littered and the play equipment is damaged. Some residents say it is the management company's job to fix it. Others say that residents who use the park every day should help look after it too.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain who is responsible for the shared park and why.","Use at least THREE words from the Word Bank (e.g. community, common good, civic responsibility) accurately.","Conclude with one practical action the residents could take."], model:"Looking after the shared park is a responsibility that belongs to both the management company and the residents, because the park serves the common good of the whole community. The company has a duty to repair damaged equipment, but residents also have a civic responsibility not to drop litter and to treat shared spaces with care, since they are the people who benefit from them every day. If everyone waits for someone else to act, the park will keep getting worse. I think residents should organise a monthly volunteering clean-up and report damage quickly, so that the community and the company work together.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; practical action is realistic and well-justified."]], starters:["The shared park is the responsibility of ___ because ___.","Residents have a civic responsibility to ___.","This matters for the common good because ___.","One practical action the residents could take is ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Community Ethics Charter", steps:["In groups of 3–4, choose ONE community you belong to (e.g. your school, your residential area, a sports club).","Identify 3 rights members of this community should enjoy and 3 responsibilities they should accept.","Identify one real problem this community faces and propose an ethical solution.","Design a one-page charter or poster presenting your rights, responsibilities and solution.","Present your charter to the class in a 3-minute pitch. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Rights and responsibilities are vague; no problem identified."],["3–4","Basic rights and responsibilities; problem named but solution is unclear."],["5–6","Clear, relevant rights and responsibilities; a realistic problem and ethical solution."],["7–8","Thoughtful, well-balanced rights and responsibilities; solution is practical, ethical and convincingly justified."]]},
  game:{type:"sort", title:"Good for the Community or Not?", prompt:"Sort each action: does it support the common good of a community, or does it harm it?", bins:["Supports the common good","Harms the community"], items:[["Volunteering at a Ramadan iftar distribution",0],["Leaving rubbish on the beach after a picnic",1],["Checking on an elderly neighbour",0],["Playing loud music late at night in a shared building",1],["Reporting a broken streetlight to the authorities",0],["Parking across a neighbour's driveway",1],["Joining a desert or beach clean-up",0],["Damaging play equipment in a shared park",1]]},
  quiz:[["What is a community?",["A group of people who share a place, interests, values or identity","A single family living in one house","A type of government"],0],["What does 'common good' mean?",["What benefits only the richest members","What benefits all or most members of a community","What one person wants"],1],["Which is an example of civic responsibility?",["Ignoring local laws","Only looking after your own home","Obeying laws and helping to keep shared spaces safe and clean"],2],["What is volunteering?",["Freely giving time or effort to help others without being paid","A paid part-time job","A school punishment"],0],["In the extract, who is responsible for the shared park?",["Only the management company","Both the company and the residents","Nobody"],1],["Can a person belong to more than one community?",["No, only one at a time","Only if they move house","Yes, for example a school, a neighbourhood and a sports club"],2],["Which Emirati value is about caring for the people who live near you?",["Competition","Neighbourliness (al-jar)","Isolation"],1],["Why do communities need ethics?",["To guide members to act fairly and responsibly so everyone can live well together","To make life more difficult","Ethics only matter for individuals, not communities"],0]],
  exit:"Name ONE community you belong to and ONE responsibility you have as a member of it.",
  copy:{facts:["A community is a group of people who share a place, interests, values or identity — and everyone belongs to several.","Community members have rights (such as safety and fair treatment) and responsibilities (such as obeying laws and caring for shared spaces).","Ethical communities put the common good first; in the UAE this is reflected in neighbourliness, volunteering and the 2025 Year of Community."]},
  next:"Next lesson: we continue Unit 1 by exploring why valuing diversity matters in communities like ours."
 },
 {
  id:"l2", lesson:2, title:"Valuing Diversity", unit:"Unit 1: Ethics in Communities & Nations", art:"tolerance",
  dna:"Recap: in one sentence, explain what the 'common good' means from last lesson. Now think: the UAE is home to people from around 200 nationalities. Write down ONE benefit and ONE challenge of living in such a diverse country.",
  dnaQs:["In one sentence, what does the 'common good' mean?","Name ONE benefit of living in a very diverse country like the UAE.","Name ONE challenge of living in a very diverse country."],
  dnaHint:"The common good is what benefits all or most members of a community. Benefits of diversity include learning new languages, foods, ideas and perspectives. A challenge might be misunderstandings caused by different customs or languages — which is why respect and communication matter.",
  intentions:["Understand what diversity is and the different forms it can take.","Explore why valuing diversity strengthens communities and nations.","Evaluate ways to respond to stereotypes and prejudice respectfully."],
  criteria:["I can explain what diversity is and give examples of its different forms.","I can explain why valuing diversity benefits communities.","I can evaluate ways to challenge stereotypes and prejudice respectfully."],
  concept:{key:"Culture", related:"Identity, Perspective", soi:"Valuing diversity allows communities to benefit from different perspectives and live together peacefully.", context:"Identities and Relationships — exploring how people with different identities and cultures live together.", uae:"The UAE's Ministry of Tolerance and Coexistence, the 2019 Year of Tolerance, the Document on Human Fraternity signed in Abu Dhabi (2019) and the Abrahamic Family House; links to English and Individuals & Societies."},
  words:[["Diversity","The variety of differences between people, such as culture, language, religion, ability and background."],["Tolerance","Accepting and respecting people whose beliefs, customs or opinions differ from your own."],["Coexistence","Living together peacefully despite differences."],["Stereotype","A fixed, over-simplified idea about a whole group of people."],["Prejudice","An unfair opinion about a person or group formed without knowledge or reason."],["Inclusion","Making sure everyone feels and is treated as a valued member of a group."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE UAE initiative that promotes tolerance and coexistence (e.g. the Ministry of Tolerance and Coexistence, the Year of Tolerance 2019, the Document on Human Fraternity, the Abrahamic Family House).","Research it using at least two reliable sources.","Record: what it is, when it began, and what it aims to achieve.","Explain how it helps people from different backgrounds live together."], prompts:["The initiative I chose and my two sources","What it is and when it began","What it aims to achieve","How it helps people from different backgrounds live together"], success:"Good answers give accurate key facts: for example, the Document on Human Fraternity was signed in Abu Dhabi in February 2019 by Pope Francis and the Grand Imam of Al-Azhar, and the Abrahamic Family House in Abu Dhabi contains a mosque, a church and a synagogue. Strong answers explain the purpose of the initiative, not just its name. For the top band, use two credible sources (e.g. official UAE government websites) and make a clear link to coexistence."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"During a group project, one student says, “We shouldn't let him present — people from his country are never good at speaking English.” The student being talked about hears the comment and goes quiet for the rest of the lesson.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain what is wrong with the comment and what effect it had.","Use at least THREE words from the Word Bank (e.g. stereotype, prejudice, inclusion) accurately.","Suggest how a classmate could respond respectfully in the moment."], model:"The comment is wrong because it is based on a stereotype — a fixed, over-simplified idea that everyone from one country shares the same weakness. It shows prejudice, as the student judged his classmate's ability without any knowledge or evidence. The effect was serious: the classmate felt excluded and stopped taking part, so the group lost his ideas and the class lost a sense of inclusion. A classmate could respond calmly by saying, “That's not fair — let's judge each other on what we actually do,” and then invite him to share his part of the presentation.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; suggested response is respectful and realistic."]], starters:["The comment is wrong because it is based on a ___.","This shows prejudice because ___.","The effect on the classmate was ___.","A classmate could respond by ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Celebrating Our Diversity Campaign", steps:["In groups of 3–4, design a short school campaign that celebrates the diversity of your year group (e.g. a languages wall, a 'shared traditions' display, a short video).","Explain how your campaign promotes tolerance, coexistence and inclusion.","Identify one stereotype your campaign could help to challenge, and explain how.","Make sure every culture is represented respectfully and accurately, without generalising.","Present your campaign to the class in a 3-minute pitch. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Campaign idea is vague; little link to diversity or tolerance."],["3–4","Basic campaign with limited explanation; stereotype named but not addressed."],["5–6","Clear, respectful campaign; explains its link to tolerance; addresses a stereotype."],["7–8","Creative, realistic and respectful campaign; insightful explanation of how it challenges stereotypes and builds inclusion."]]},
  game:{type:"sort", title:"Fact, Respect or Stereotype?", prompt:"Sort each statement: does it value diversity respectfully, or is it a stereotype or prejudice?", bins:["Values diversity","Stereotype / prejudice"], items:[["People in our class speak many different languages, and we can learn from each other.",0],["Everyone from that country is bad at sport.",1],["Different families may celebrate the same occasion in different ways.",0],["Girls are not good at science.",1],["Asking a classmate politely about their traditions to learn more.",0],["Refusing to work with someone because of their nationality.",1],["Judging people by what they do, not where they come from.",0],["All teenagers are lazy.",1]]},
  quiz:[["What is diversity?",["The variety of differences between people, such as culture, language and background","Everyone being exactly the same","A type of school subject"],0],["What is a stereotype?",["A fact proven by research","A fixed, over-simplified idea about a whole group of people","A type of music player"],1],["What does 'coexistence' mean?",["Living in separate places","Competing to be the best culture","Living together peacefully despite differences"],2],["In the extract, why is the comment an example of prejudice?",["It judged the classmate's ability without knowledge or evidence","It was based on his actual presentation","It was a helpful suggestion"],0],["Where was the Document on Human Fraternity signed in 2019?",["Cairo","Abu Dhabi","Rome"],1],["What does the Abrahamic Family House in Abu Dhabi contain?",["A museum and a library","Three schools","A mosque, a church and a synagogue"],2],["Which year did the UAE name the 'Year of Tolerance'?",["2019","2001","2030"],0],["What is the best way to respond to a stereotype?",["Laugh along so you fit in","Calmly challenge it and judge people on what they actually do","Ignore the person it is about"],1]],
  exit:"Write ONE thing you have learned from someone with a different background from your own.",
  copy:{facts:["Diversity means the variety of differences between people, such as culture, language, religion, ability and background.","Stereotypes and prejudice are unfair because they judge people without knowledge — we should judge people by what they do.","The UAE promotes tolerance through the Ministry of Tolerance and Coexistence, the 2019 Year of Tolerance, the Document on Human Fraternity and the Abrahamic Family House."]},
  next:"Next lesson: we continue Unit 1 by exploring how consultative government (Shura) developed in the UAE."
 },
 {
  id:"l3", lesson:3, title:"The Development of Consultative Government (Shura) in the UAE", unit:"Unit 1: Ethics in Communities & Nations", art:"power",
  dna:"Recap: in one sentence, explain the difference between a stereotype and diversity. Now think: when your family has an important decision to make, do family members discuss it together first? Write down ONE reason why asking others for their views before deciding is a good idea.",
  dnaQs:["In one sentence, what is the difference between a stereotype and diversity?","Write ONE reason why asking others for their views before making a decision is a good idea."],
  dnaHint:"Diversity is the real variety of differences between people; a stereotype is an unfair, over-simplified idea about a whole group. Asking others first is wise because you hear more ideas, notice problems you missed, and people are more likely to support a decision they helped to shape.",
  intentions:["Understand the meaning of Shura (consultation) and its roots in Islamic and Emirati tradition.","Explore how the traditional Majlis developed into the Federal National Council (FNC).","Evaluate why consultation is an important ethical principle in government."],
  criteria:["I can explain what Shura means and where the idea comes from.","I can describe key stages in the development of consultative government in the UAE.","I can evaluate why consultation matters for fair and effective decision-making."],
  concept:{key:"Systems", related:"Governance, Development", soi:"Consultation allows leaders and citizens to share in decisions, building trust and stronger nations.", context:"Orientation in Space and Time — exploring how traditions of governance have developed over time.", uae:"The Majlis tradition, the Federal National Council established in 1971, FNC elections since 2006 and equal representation of women since 2019; links to Individuals & Societies (government and citizenship)."},
  words:[["Shura","An Arabic word meaning consultation: seeking advice and views before making a decision."],["Majlis","A traditional gathering place where people meet the ruler or community leaders to discuss issues and raise concerns."],["Consultation","Asking for and listening to other people's views before deciding."],["Federal National Council (FNC)","The UAE's parliamentary body, which discusses laws and national issues and advises the government."],["Electoral college","A selected group of citizens who vote to elect members of the FNC."],["Participation","Taking part in decisions and community life."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Research the development of consultative government in the UAE using at least two reliable sources (e.g. the official FNC or UAE government websites).","Create a simple timeline with at least FOUR key stages, starting with the traditional Majlis.","For each stage, write one sentence explaining how it increased consultation or participation.","Note one way the Majlis tradition still continues today."], prompts:["My two sources","Stage 1 and how it supported consultation","Stages 2–4 and how each increased participation","One way the Majlis tradition continues today"], success:"A strong timeline could include: the traditional Majlis, where rulers listened to people's concerns; the establishment of the FNC under the UAE Constitution in 1971 with 40 members from all seven emirates; the first FNC elections in 2006, when half of the members were elected by an electoral college; the later expansion of the electoral college; and the 2019 decision that women would make up 50% of the FNC. Strong answers explain how each stage increased participation, not just list dates. For the top band, use two credible sources and avoid facts you cannot verify."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A student council must decide how to spend its budget for the year. The president says, “I already know what's best, so I'll just decide.” Another member suggests holding a meeting where every class representative can share their year group's views first.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain which approach reflects the principle of Shura, and why it is better.","Use at least THREE words from the Word Bank (e.g. Shura, consultation, participation) accurately.","Link your answer to how the Majlis or the FNC works in the UAE."], model:"The second suggestion reflects the principle of Shura, because it involves consultation with every class representative before a decision is made. This is better than the president deciding alone, as listening to different views helps the council notice needs it might have missed and makes students more likely to accept the final decision because they took part in it. The same idea is found in the UAE, where the traditional Majlis allowed people to share their concerns directly with their leaders, and today the Federal National Council allows citizens' representatives to discuss laws and national issues. Participation through consultation leads to fairer and wiser decisions.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; clear, accurate link to the Majlis or FNC."]], starters:["The approach that reflects Shura is ___ because ___.","Consultation is better than deciding alone because ___.","This is similar to the Majlis / FNC in the UAE, where ___.","Participation leads to fairer decisions because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Our Class Majlis", steps:["As a class, choose ONE real school issue to discuss (e.g. break-time activities, a charity to support, a class reward).","In groups of 3–4, prepare your group's view and the reasons for it.","Hold a class Majlis: each group shares its view respectfully while others listen, then the class agrees a recommendation.","Write a short summary of the recommendation, showing how different views were considered.","Reflect: how did consultation change the final decision? Use Word Bank vocabulary in your reflection."], rubric:[["1–2","Little participation; views not explained or listened to."],["3–4","Group view shared with basic reasons; limited listening to others."],["5–6","Clear, well-reasoned view; respectful listening; recommendation reflects several views."],["7–8","Thoughtful, persuasive contribution; genuine engagement with other views; insightful reflection on the value of consultation."]]},
  game:{type:"sort", title:"Consultation or Not?", prompt:"Sort each example: does it show Shura (consultation), or a decision made without consultation?", bins:["Shows consultation (Shura)","No consultation"], items:[["A ruler holding an open Majlis to hear citizens' concerns",0],["FNC members discussing a draft law before it is passed",0],["A team captain choosing the team's tactics without asking anyone",1],["A family discussing a big decision together before agreeing",0],["A student council surveying students about how to spend its budget",0],["One person changing a group project's topic without telling the others",1],["A school asking parents for feedback on a new policy",0],["Ignoring everyone's suggestions because you think you know best",1]]},
  quiz:[["What does the Arabic word 'Shura' mean?",["Celebration","Consultation","Competition"],1],["What is a Majlis?",["A traditional gathering place where people meet leaders to discuss issues","A type of desert vehicle","A government tax"],0],["In which year was the Federal National Council established?",["1990","2006","1971"],2],["How many members does the FNC have?",["40","100","7"],0],["What happened in 2006?",["The UAE was founded","The first FNC elections were held, with half of the members elected by an electoral college","The FNC was closed"],1],["What decision was made about women's representation in the FNC in 2019?",["Women could no longer be members","Women would make up 50% of the FNC","Only one woman could be a member"],1],["In the extract, which approach reflects Shura?",["The president deciding alone","Cancelling the budget","Holding a meeting where every representative shares their views"],2],["Why is consultation an important ethical principle in government?",["It makes decisions fairer and builds trust between leaders and citizens","It makes decisions slower for no reason","It means leaders never have to decide"],0]],
  exit:"In one sentence, explain how the traditional Majlis and today's FNC both reflect the principle of Shura.",
  copy:{facts:["Shura means consultation — seeking others' views before deciding — and is an important value in Islam and Emirati tradition.","The traditional Majlis allowed people to share concerns directly with their rulers; this tradition continues today.","The Federal National Council was established in 1971 with 40 members; elections began in 2006, and since 2019 women make up 50% of its members."]},
  next:"Next lesson: we continue Unit 1 by exploring what ethics means in the context of whole nations."
 },
 {
  id:"l4", lesson:4, title:"Ethics in the Context of Nations", unit:"Unit 1: Ethics in Communities & Nations", art:"globe",
  dna:"Recap: in one sentence, explain what Shura means. Now think: just as people have responsibilities to their community, countries have responsibilities too. Write down ONE responsibility you think a country has toward its own people, and ONE it has toward other countries.",
  dnaQs:["In one sentence, what does Shura mean?","Name ONE responsibility a country has toward its own people.","Name ONE responsibility a country has toward other countries."],
  dnaHint:"Shura means consultation — seeking views before deciding. A country's responsibilities to its people include keeping them safe and providing education and healthcare. Toward other countries, it might respect their borders, keep agreements and help in times of crisis.",
  intentions:["Understand what a nation is and the ethical responsibilities of nations.","Explore the shared responsibilities between a state and its citizens.","Evaluate how nations can act ethically toward one another, using UAE examples."],
  criteria:["I can explain what a nation is and describe its ethical responsibilities.","I can describe the duties a state and its citizens have toward each other.","I can evaluate an example of a nation acting ethically on the world stage."],
  concept:{key:"Global interactions", related:"Responsibility, Citizenship", soi:"Nations, like individuals, have ethical responsibilities to their citizens and to the wider world.", context:"Globalisation and Sustainability — exploring how nations relate to one another and share responsibility for the world.", uae:"The formation of the UAE federation on 2 December 1971, UAE membership of the United Nations, and the UAE's international humanitarian and development aid; links to Individuals & Societies."},
  words:[["Nation","A large group of people who share a country, government, history or identity."],["State","An organised political community with its own government, territory and laws."],["Citizen","A legally recognised member of a country, with rights and duties."],["Sovereignty","The right of a country to govern itself without outside interference."],["International cooperation","Countries working together to solve shared problems."],["Humanitarian aid","Help, such as food, water, shelter or medicine, given to people in a crisis."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE example of the UAE acting ethically on the world stage (e.g. humanitarian aid after a natural disaster, development projects, support for refugees, international environmental action).","Research it using at least two reliable sources (e.g. official UAE government websites, UN agencies, the Emirates Red Crescent).","Record: what the UAE did, who it helped, and which ethical principle it reflects.","Note one reason why helping other nations also benefits the UAE and the world."], prompts:["The example I chose and my two sources","What the UAE did and who it helped","The ethical principle it reflects","Why this also benefits the UAE and the world"], success:"Good examples include emergency aid delivered after earthquakes or floods, the work of the Emirates Red Crescent, support for refugees, and international climate action such as hosting COP28 in Dubai in 2023. Strong answers name a clear ethical principle (e.g. compassion, cooperation, valuing every human life) and explain the link. For the top band, use two credible sources and explain how ethical action builds trust and stability between nations."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A powerful earthquake strikes a country far away. Thousands of people are left without homes, clean water or medical care. Some people say, “It's not our country, so it's not our problem.” Others say nations have a duty to help one another in times of crisis.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), argue whether nations have an ethical responsibility to help other countries in a crisis.","Use at least THREE words from the Word Bank (e.g. nation, humanitarian aid, international cooperation) accurately.","Use one example of how the UAE responds to crises abroad."], model:"Nations do have an ethical responsibility to help other countries in a crisis, because every human life has equal value, wherever a person lives. When an earthquake leaves people without homes, water or medical care, humanitarian aid can save lives that the affected country may not be able to protect alone. International cooperation also builds trust between nations, so that help is returned when another country faces disaster. The UAE shows this responsibility by sending emergency aid, such as food, shelter and medical supplies, to countries affected by natural disasters. Therefore, saying “it's not our problem” ignores the shared humanity that connects every nation.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured argument; 3+ key terms used accurately; relevant, accurate UAE example used."]], starters:["Nations do / do not have a responsibility to help because ___.","Humanitarian aid matters in a crisis because ___.","International cooperation builds ___.","For example, the UAE ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"An Ethical Nation Manifesto", steps:["In groups of 3–4, imagine you are advising a new, fictional nation.","Write 3 duties the state should have toward its citizens, and 3 duties citizens should have toward their nation.","Write 2 principles for how your nation should treat other countries.","For each point, justify it with an ethical reason, using a UAE or real-world example where possible.","Present your manifesto as a poster or short presentation in 3 minutes. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Duties are vague or missing; little justification."],["3–4","Basic duties listed with limited justification."],["5–6","Clear duties for state, citizens and international relations, each with a reasonable justification."],["7–8","Thoughtful, balanced manifesto; well-justified duties supported by accurate real-world examples."]]},
  game:{type:"sort", title:"Whose Responsibility?", prompt:"Sort each responsibility: does it belong mainly to the state (government), or to citizens?", bins:["The state's responsibility","Citizens' responsibility"], items:[["Providing schools and healthcare",0],["Obeying the country's laws",1],["Protecting the country's borders and keeping people safe",0],["Respecting national symbols such as the flag",1],["Making laws that treat people fairly",0],["Protecting public property and the environment",1],["Helping other countries in times of disaster",0],["Being honest and contributing positively to society",1]]},
  quiz:[["What is a nation?",["A large group of people who share a country, government, history or identity","A single city","A type of school"],0],["What does 'sovereignty' mean?",["A type of currency","A trade agreement","The right of a country to govern itself without outside interference"],2],["When was the UAE federation formed?",["1 January 2000","2 December 1971","2 December 1950"],1],["Which of these is a responsibility of citizens?",["Printing the national currency","Obeying the country's laws","Signing international treaties"],1],["What is humanitarian aid?",["Money spent on a country's army","A type of tourism","Help, such as food, water, shelter or medicine, given to people in a crisis"],2],["Why should nations help each other in a crisis?",["Because every human life has value and cooperation builds trust","Because they are forced to by law in every case","There is no reason to help"],0],["Which global event did the UAE host in Dubai in 2023?",["The Olympic Games","COP28, the UN climate change conference","The football World Cup"],1],["In the extract, the view “It's not our country, so it's not our problem” ignores…",["The cost of travel","The weather","The shared humanity that connects every nation"],2]],
  exit:"Write ONE responsibility a nation has to the wider world, and ONE way the UAE meets it.",
  copy:{facts:["A nation has ethical responsibilities to its own citizens (safety, fairness, education, healthcare) and to other nations.","Citizens also have duties to their nation, such as obeying laws, protecting public property and contributing positively.","The UAE, formed on 2 December 1971, acts ethically on the world stage through humanitarian aid and international cooperation."]},
  next:"Next lesson: we continue Unit 1 by exploring how to deal with conflict."
 },
 {
  id:"l5", lesson:5, title:"Dealing with Conflict", unit:"Unit 1: Ethics in Communities & Nations", art:"reason",
  dna:"Recap: in one sentence, name one responsibility a nation has toward other nations. Now think: without naming anyone, describe a small disagreement that often happens between friends or siblings. What usually makes it worse, and what usually makes it better?",
  dnaQs:["Name one responsibility a nation has toward other nations.","Describe a common small disagreement between friends or siblings (no names).","What usually makes it worse, and what usually makes it better?"],
  dnaHint:"A nation's responsibility could be helping in a crisis or respecting other countries' sovereignty. Disagreements often get worse through shouting, blaming, name-calling or ignoring the other person, and better through calming down, listening, and explaining how you feel.",
  intentions:["Understand what conflict is and its common causes.","Explore different ways people respond to conflict and their consequences.","Apply positive strategies to deal with a conflict situation."],
  criteria:["I can explain what conflict is and identify its common causes.","I can compare different responses to conflict and their consequences.","I can apply positive strategies to deal with a conflict."],
  concept:{key:"Relationships", related:"Conflict, Communication", soi:"How people respond to conflict determines whether relationships are damaged or strengthened.", context:"Identities and Relationships — exploring how people manage disagreement in relationships and communities.", uae:"Islamic and Emirati values of patience (sabr), self-control and good speech; links to English (speaking and listening) and wellbeing."},
  words:[["Conflict","A disagreement or clash between people or groups with different needs, views or interests."],["Escalate","To become more serious or intense."],["De-escalate","To make a situation calmer and less intense."],["Empathy","Understanding and sharing another person's feelings."],["Compromise","An agreement in which each side gives up something to reach a solution."],["Active listening","Listening carefully to understand, without interrupting, and showing you have understood."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Research common styles of responding to conflict (e.g. avoiding, competing, giving in, compromising, collaborating).","Use at least two reliable sources (e.g. educational or wellbeing websites).","Record: what each style looks like, and one advantage and one disadvantage of each.","Note which style you think works best in most school situations, and why."], prompts:["My two sources","The conflict styles I found and what each looks like","One advantage and one disadvantage of each style","The style I think works best in school, and why"], success:"Common styles include avoiding (walking away), competing (trying to win), accommodating (giving in), compromising (each side gives a little) and collaborating (working together to find a solution that meets both sides' needs). Strong answers recognise that no style is always right — avoiding can be useful to calm down, but not as a permanent solution. For the top band, use two credible sources and justify which style works best in school with a clear example."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Two classmates are working together on a science project. One feels she is doing all the work. Instead of talking about it, she posts an angry message about her partner in the class group chat. Her partner replies with an insult, and soon other students join in.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain how this conflict escalated.","Use at least THREE words from the Word Bank (e.g. escalate, de-escalate, empathy) accurately.","Suggest TWO things either student could have done to deal with the conflict positively."], model:"This conflict escalated because the first student chose to post her frustration publicly instead of speaking to her partner directly, which embarrassed him and made him respond with an insult. Once other students joined in, a private disagreement about workload became a public argument, making it much harder to solve. To de-escalate, she could have spoken to her partner privately and calmly, using active listening to understand why he had done less work. Her partner could have shown empathy by recognising her frustration and offering a compromise, such as agreeing to complete the next section himself.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; two realistic, positive strategies suggested."]], starters:["The conflict escalated because ___.","Posting publicly made things worse because ___.","To de-escalate, she could have ___.","Her partner could have shown empathy by ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Conflict Toolkit Guide", steps:["In groups of 3–4, create a short guide for younger students on dealing with conflict.","Include: common causes of conflict, signs that a conflict is escalating, and at least FOUR positive strategies.","Include one realistic, fictional scenario showing a conflict handled badly and then handled well.","Design your guide as a leaflet, poster or short slideshow.","Present your guide to the class in 3 minutes. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Guide is vague; few or unclear strategies."],["3–4","Basic guide with some strategies; scenario is limited."],["5–6","Clear guide with four relevant strategies and a realistic scenario."],["7–8","Well-designed, age-appropriate guide; strategies are practical and well-explained; scenario clearly shows the difference positive strategies make."]]},
  game:{type:"sort", title:"Escalate or De-escalate?", prompt:"Sort each response: does it escalate (worsen) a conflict, or de-escalate (calm) it?", bins:["De-escalates","Escalates"], items:[["Taking a few deep breaths before replying",0],["Shouting over the other person",1],["Saying “I feel upset when…” instead of blaming",0],["Posting about the argument on social media",1],["Listening to the other side without interrupting",0],["Name-calling or insulting",1],["Suggesting a compromise",0],["Bringing friends in to take your side",1]]},
  quiz:[["What is conflict?",["A disagreement between people with different needs, views or interests","Always a physical fight","A type of game"],0],["What does 'escalate' mean?",["To become calmer","To become more serious or intense","To end completely"],1],["Which is an example of active listening?",["Checking your phone while the other person talks","Interrupting to give your view","Listening carefully without interrupting and showing you understand"],2],["What is a compromise?",["An agreement in which each side gives up something to reach a solution","When one person wins and the other loses","Refusing to talk"],0],["In the extract, what first caused the conflict to escalate?",["The students talked privately","The teacher stepped in","Posting an angry message in the class group chat"],2],["Which statement shows empathy?",["“That's your problem.”","“I can see why you feel frustrated.”","“Whatever.”"],1],["Is conflict always a bad thing?",["Yes, it always ruins relationships","No — handled well, it can solve problems and strengthen relationships","Only if adults are involved"],1],["Which Islamic and Emirati value helps us control our reactions during conflict?",["Patience (sabr)","Pride","Revenge"],0]],
  exit:"Write ONE strategy you will use next time you disagree with someone, and why it helps.",
  copy:{facts:["Conflict is a disagreement between people with different needs, views or interests — it is a normal part of life.","Conflicts escalate through shouting, blaming, insults and going public; they de-escalate through calm talk, active listening and empathy.","Islamic and Emirati values such as patience (sabr) and good speech help people deal with conflict positively."]},
  next:"Next lesson: we complete Unit 1 by exploring how conflicts can be resolved peacefully, including the UAE's role in peace-building."
 },
 {
  id:"l6", lesson:6, title:"Resolving Conflict Peacefully", unit:"Unit 1: Ethics in Communities & Nations", art:"fair",
  dna:"Unit 1 vocabulary check! Match each term to its definition as fast as you can: Common good, Diversity, Shura, Sovereignty, De-escalate. This is our final lesson of Unit 1 — let's see how much has stuck.",
  dnaQs:["Common good and Diversity — what does each mean?","Shura and Sovereignty — what does each mean?","De-escalate — what does it mean?"],
  dnaHint:"Common good: what benefits all or most members of a community. Diversity: the variety of differences between people. Shura: consultation before making a decision. Sovereignty: a country's right to govern itself. De-escalate: to make a situation calmer and less intense.",
  intentions:["Understand peaceful methods of resolving conflict, including negotiation and mediation.","Explore the role of the UAE in peace-building and mediation between nations.","Reflect on learning across Unit 1 and connect ethics in communities to ethics in nations."],
  criteria:["I can explain the difference between negotiation and mediation.","I can describe an example of the UAE's role in peace-building.","I can connect ideas from across Unit 1 to peaceful conflict resolution."],
  concept:{key:"Relationships", related:"Peace, Global interactions", soi:"Peaceful methods such as negotiation and mediation allow people and nations to resolve conflict while protecting relationships.", context:"Fairness and Development — exploring how individuals and nations build and keep peace.", uae:"The UAE's diplomatic role in peace-building, including supporting the 2018 Ethiopia–Eritrea peace agreement and mediating prisoner exchanges between Russia and Ukraine; links to Individuals & Societies."},
  words:[["Negotiation","A discussion between the people in a conflict to reach an agreement themselves."],["Mediation","When a neutral third person (a mediator) helps both sides talk and reach an agreement."],["Mediator","A neutral person who helps others resolve a conflict, without taking sides."],["Neutral","Not supporting either side in a disagreement."],["Reconciliation","Restoring friendly relations after a conflict."],["Peace-building","Actions that help create lasting peace and prevent conflict from returning."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE example of the UAE's role in peace-building or mediation (e.g. support for the 2018 Ethiopia–Eritrea peace agreement, mediating prisoner exchanges between Russia and Ukraine, humanitarian support for peace in a region).","Research it using at least two reliable sources (e.g. official UAE government websites, reputable news organisations).","Record: who was in conflict, what role the UAE played, and what was achieved.","Explain why a neutral, trusted country can be a helpful mediator."], prompts:["The example I chose and my two sources","Who was in conflict","The role the UAE played and what was achieved","Why a neutral, trusted country can be a helpful mediator"], success:"Strong answers describe the UAE's role accurately and carefully — for example, the UAE supported and hosted leaders during the 2018 peace process between Ethiopia and Eritrea, and since 2024 has helped mediate several prisoner exchanges between Russia and Ukraine. Avoid exaggerating: the UAE often supports or facilitates peace rather than solving a conflict alone. For the top band, use two credible sources and explain clearly why trust and neutrality make a mediator effective."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Two groups of students both want to use the school's only free room at lunchtime: one group for chess club and the other for a robotics project. Both groups have tried negotiating, but they keep arguing. A Year 11 peer mediator offers to help.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain how mediation could help the two groups resolve their conflict.","Use at least THREE words from the Word Bank (e.g. mediation, neutral, negotiation) accurately.","Suggest a fair solution the mediator could help them reach."], model:"Mediation could help because the two groups have already tried negotiation without success, and a neutral mediator can help them listen to each other instead of arguing. The mediator would let each group explain its needs without interruption, help them see the other side's point of view, and guide them towards a solution they both accept, without taking sides. A fair solution could be to share the room on alternate days, or to split each lunchtime in half, so both clubs can meet. This kind of agreement supports reconciliation, because neither group feels it has lost.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; the suggested solution is fair and realistic."]], starters:["Mediation could help because ___.","A neutral mediator would ___.","A fair solution could be ___.","This supports reconciliation because ___."]},
  task3:{title:"Project Task (Unit Showcase)", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Peace Summit Role-Play", steps:["In groups of 3–4, you will receive a fictional conflict card (between two classmates, two communities or two fictional nations).","Assign roles: two sides and one or two neutral mediators.","Role-play a mediation following clear steps: each side explains, the mediator summarises, both sides suggest solutions, and they agree a fair outcome.","Write a short 'peace agreement' showing what each side agreed to.","Reflect: which ideas from Unit 1 (community ethics, diversity, Shura, nations, conflict) helped you reach peace? Use Word Bank vocabulary in your reflection."], rubric:[["1–2","Role-play lacks structure; little sign of peaceful resolution."],["3–4","Basic mediation steps followed; agreement is vague."],["5–6","Clear mediation steps; fair, realistic agreement; reflection makes some links to Unit 1."],["7–8","Skilful, respectful mediation; fair and creative agreement; reflection makes insightful links across Unit 1."]]},
  game:{type:"sort", title:"Negotiation, Mediation or Neither?", prompt:"Sort each example: is it negotiation, mediation, or not a peaceful method at all?", bins:["Negotiation","Mediation","Not peaceful"], items:[["Two friends calmly discuss and agree to take turns choosing the game",0],["A peer mediator helps two students agree how to share a room",1],["Two countries' leaders meet directly to agree a trade deal",0],["A neutral country helps two nations agree a prisoner exchange",1],["Spreading rumours about the other side to win",2],["A teacher, acting neutrally, helps two classmates talk through a falling-out",1],["Refusing to speak and trying to get revenge",2],["Two siblings agree a compromise on screen time without help",0]]},
  quiz:[["What is negotiation?",["A discussion between the people in a conflict to reach an agreement themselves","Asking a judge to punish one side","Ignoring the conflict"],0],["What is mediation?",["When one side wins by force","When a neutral third person helps both sides reach an agreement","When the conflict is posted online"],1],["What does a good mediator need to be?",["On the side of their friend","Strict and punishing","Neutral and trusted by both sides"],2],["In the extract, why is mediation needed?",["Because the groups' negotiation kept failing","Because they agreed immediately","Because the room was closed"],0],["Which peace agreement in 2018 did the UAE support?",["Between Ethiopia and Eritrea","Between Brazil and Argentina","Between Canada and Mexico"],0],["How has the UAE contributed to peace between Russia and Ukraine?",["By sending armies","By helping to mediate prisoner exchanges","By refusing to talk to either side"],1],["What does 'reconciliation' mean?",["Starting a new argument","Restoring friendly relations after a conflict","Choosing a winner"],1],["How does Shura (Lesson 3) connect to peaceful conflict resolution?",["It has no connection","It means one leader decides alone","Consultation and listening to every side are key to reaching fair agreements"],2]],
  exit:"Write ONE idea from Unit 1 that you think is most important for building peace, and why.",
  copy:{facts:["Negotiation is when the sides in a conflict reach an agreement themselves; mediation is when a neutral third person helps them.","The UAE supports peace-building through diplomacy, for example the 2018 Ethiopia–Eritrea peace agreement and mediating Russia–Ukraine prisoner exchanges.","Peace in communities and nations depends on ethics, valuing diversity, consultation (Shura) and dealing with conflict calmly."]},
  next:"Unit 1: Ethics in Communities & Nations is complete! Next we move on to the next unit of the Term 1 book."
 }
];
